21	// partIsoStore 构造初始库存 12 件的已登记备件：可选登记一个保修 60 天的
22	// 产品和若干保修资格请求，用于随后预留两笔不同请求的承诺。
23	func partIsoStore(t *testing.T, requests ...string) *Store {
24		t.Helper()
25		s := NewStore()
26		if err := s.RegisterPart(partIsolationPartID, 12); err != nil {
27			t.Fatalf("register part: %v", err)
28		}
29		if len(requests) == 0 {
30			return s
31		}
32		if err := s.RegisterProduct("p-iso", t0, 60, nil); err != nil {
33			t.Fatalf("register product: %v", err)
34		}
35		for _, id := range requests {
36			if err := s.SubmitRequest(id, "p-iso", "FAULTY"); err != nil {
37				t.Fatalf("submit request %s: %v", id, err)
38			}
39		}
40		return s
41	}
42	
43	// partIsoExpiry 给出一个晚于全部操作时刻的到期时刻，各承诺可给不同时刻以
44	// 回归保障修改取回结果不会篡改其他承诺的到期时刻。
45	func partIsoExpiry(n int) time.Time {
46		return t0.Add(time.Duration(n) * day)
47	}
48	
49	// assertPartIsoAccount 断言某次 PartStatus 的库存三项为期望值。
50	func assertPartIsoAccount(t *testing.T, st *PartStatus, physical, occupied, committable int) {
51		t.Helper()
52		if st.PhysicalRemaining != physical || st.ActiveOccupied != occupied || st.Committable != committable {
53			t.Fatalf("stock account phys=%d occupied=%d committable=%d, want phys=%d occupied=%d committable=%d",
54				st.PhysicalRemaining, st.ActiveOccupied, st.Committable, physical, occupied, committable)
55		}
56	}
57	
58	// assertDetailFact 断言一条明细完整反映一笔承诺的查询当时事实：归属、原定、
59	// 已用、未用、状态与到期时刻。
60	func assertDetailFact(t *testing.T, d CommitmentDetail, requestID string, original, used, remaining int, status CommitmentStatus, expiry time.Time) {
61		t.Helper()
62		if d.RequestID != requestID || d.PartID != partIsolationPartID ||
63			d.OriginalQuantity != original || d.UsedQuantity != used || d.RemainingQuantity != remaining ||
64			d.Status != status || !d.Expiry.Equal(expiry) {
65			t.Fatalf("detail %q: req=%s part=%s orig=%d used=%d rem=%d status=%s expiry=%v; "+
66				"want req=%s orig=%d used=%d rem=%d status=%s expiry=%v",
67				d.CommitmentID, d.RequestID, d.PartID, d.OriginalQuantity, d.UsedQuantity, d.RemainingQuantity, d.Status, d.Expiry,
68				requestID, original, used, remaining, status, expiry)
69		}
70	}
