283	// TestPartStatusEmptyDetailsSnapshotStaysEmpty 没有承诺时已登记备件的明细
284	// 为空，实物剩余与可承诺数量相同；后来正常预留成功，新查询出现承诺明细，
285	// 先前取得的空结果仍保持为空，其库存数字也不随后续使用或预留改写。
286	func TestPartStatusEmptyDetailsSnapshotStaysEmpty(t *testing.T) {
287		s := partIsoStore(t, "req-later")
288	
289		empty, err := s.PartStatus(partIsolationPartID, nowOK)
290		if err != nil {
291			t.Fatalf("empty part status: %v", err)
292		}
293		if empty.PhysicalRemaining != 12 || empty.ActiveOccupied != 0 || empty.Committable != 12 {
294			t.Fatalf("empty account: %+v, want phys=12 occupied=0 committable=12", empty)
295		}
296		if len(empty.Details) != 0 {
297			t.Fatalf("empty details = %d, want 0", len(empty.Details))
298		}
299	
300		// 后来正常预留成功（时刻仍早于到期时刻）：新查询出现承诺明细。
301		expLater := partIsoExpiry(40)
302		if _, err := s.Reserve("c-later", "req-later", partIsolationPartID, 5, expLater, nowOK); err != nil {
303			t.Fatalf("reserve c-later: %v", err)
304		}
305		if _, err := s.Use("u-later-2", "c-later", 2, nowOK); err != nil {
306			t.Fatalf("use 2 from c-later: %v", err)
307		}
308		latest, err := s.PartStatus(partIsolationPartID, nowOK)
309		if err != nil {
310			t.Fatalf("latest part status: %v", err)
311		}
312		if latest.PhysicalRemaining != 10 || latest.ActiveOccupied != 3 || latest.Committable != 7 {
313			t.Fatalf("latest account: phys=%d occupied=%d committable=%d, want 10/3/7",
314				latest.PhysicalRemaining, latest.ActiveOccupied, latest.Committable)
315		}
316		if len(latest.Details) != 1 {
317			t.Fatalf("latest details = %d, want 1", len(latest.Details))
318		}
319		assertDetailFact(t, latest.Details[0], "req-later", 5, 2, 3, CommitmentActive, expLater)
320	
321		// 先前的空结果仍保持为空，三项数字也保留当时内容。
322		if len(empty.Details) != 0 {
323			t.Fatalf("earlier empty result gained details: %+v", empty.Details)
324		}
325		if empty.PhysicalRemaining != 12 || empty.ActiveOccupied != 0 || empty.Committable != 12 {
326			t.Fatalf("earlier empty result account changed: phys=%d occupied=%d committable=%d, want 12/0/12",
327				empty.PhysicalRemaining, empty.ActiveOccupied, empty.Committable)
328		}
