134	// 编号分别使用两件。哪组先成功不作保证，但只能有一份内容成为成功记录：胜出
135	// 组全部成功并返回同一结果，落败组全部 ErrConflict。结束后实物剩余八件、有效
136	// 占用六件、可承诺两件；只有胜出承诺已用两件，落败承诺保持未使用。
137	func TestConcurrentUseSameIDDifferentCommitmentSingleWinner(t *testing.T) {
138		s := newStore(t)
139		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
