144		}
145	
146		const n = 12
147		calls := make([]concurrentUseCall, 0, 2*n)
148		for i := 0; i < n; i++ {
149			calls = append(calls, concurrentUseCall{"uX", "c1", 2, nowOK.Add(time.Duration(i) * time.Minute)})
150		}
151		for i := 0; i < n; i++ {
152			calls = append(calls, concurrentUseCall{"uX", "c2", 2, nowOK.Add(time.Duration(i) * time.Minute)})
153		}
154		results := fanOutConcurrentUse(s, calls)
155	
156		// 胜出者由实际数量判定（调用结果必须与实际扣减对应）：恰有一笔承诺已用两件。
157		c1c, _ := s.Commitment("c1")
158		c2c, _ := s.Commitment("c2")
159		var winner, loser string
160		switch {
161		case c1c.Used == 2 && c2c.Used == 0:
162			winner, loser = "c1", "c2"
163		case c1c.Used == 0 && c2c.Used == 2:
164			winner, loser = "c2", "c1"
165		default:
