287			t.Fatalf("loser content retry: got %v, want ErrConflict", err)
288		}
289		c1b, _ := s.Commitment("c1")
290		if c1b.Used != winnerQty {
291			t.Fatalf("c1 used after retries = %d, want still %d", c1b.Used, winnerQty)
292		}
293	}
