35	// assertExcludedCodes 断言取回的产品资料中除外代码集合恰好等于 want。
36	func assertExcludedCodes(t *testing.T, p Product, want ...string) {
37		t.Helper()
38		if len(p.ExcludedCodes) != len(want) {
39			t.Fatalf("excluded codes = %v, want exactly %v", p.ExcludedCodes, want)
40		}
41		for _, c := range want {
42			if _, ok := p.ExcludedCodes[c]; !ok {
43				t.Fatalf("excluded codes = %v, want to contain %q", p.ExcludedCodes, c)
44			}
45		}
46	}
